/* ── TYPE TREATMENT — weight, tracking and case ───────────────────────────── */
/* Weight and tracking ride the --text-* tokens above; CASE cannot (Tailwind's
 * type namespace has no text-transform key), so it lives here with the utilities
 * that read it. `type-eyebrow` is the whole label treatment as one token —
 * before it existed the library re-spelled it 17 times at three different
 * tracking values, which is what an un-named token looks like. */
:root {
  --case-heading: none;
  --case-eyebrow: uppercase;
  --tracking-eyebrow: 0.08em;
  --weight-eyebrow: 500;
}

@utility type-eyebrow {
  font-size: var(--text-micro);
  line-height: var(--text-micro--line-height);
  letter-spacing: var(--tracking-eyebrow);
  font-weight: var(--weight-eyebrow);
  text-transform: var(--case-eyebrow);
}

@utility case-heading {
  text-transform: var(--case-heading);
}

/* ── THE DISPLAY FAMILY'S CONSUMER (FR-06) ────────────────────────────────── */
/* `--font-display` was emitted for months and NOTHING read it. Every heading in
 * the library inherited `font-sans`, so the two-family packs moved a real token
 * and changed nothing on the canvas — a knob that lies, and the system's own
 * documented counter-example.
 *
 * `:where()` is the whole design of the fix. It carries ZERO specificity, so
 * any font utility a component sets wins without `!important` and without a
 * cascade puzzle — opting a heading back into the text face is `font-sans` and
 * nothing else. Matching ELEMENTS rather than `.text-h1` keeps the token layer
 * from depending on utility class names, and it deliberately stops at h1–h3:
 * CardTitle is a <div>, table column heads are <th>, and a display face has no
 * business in either.
 *
 * With a one-family pack --font-display IS --font-sans and this rule is a no-op,
 * which is why it can ship on by default. The one-family rule is still the
 * house answer; it is now a choice rather than a limitation. */
@layer base {
  :where(h1, h2, h3) {
    font-family: var(--font-display);
  }
}

/* ── FORM — the hairline's weight (FR-12) ─────────────────────────────────── */
/* `border` compiles to a literal `border-width: 1px`, so a border-weight token
 * with no way into that utility is a token nobody spends. Re-declaring the
 * family here is what gives it ~660 consumers instead of zero.
 *
 * The mechanism is the same one the border-COLOR rule above already relies on:
 * this file is imported after `tailwindcss`, so within `@layer utilities` these
 * rules land second and win on the one property they name. Everything else
 * Tailwind's own `.border` sets — `border-style`, the `--tw-border-style`
 * plumbing — is untouched, because two rules with the same selector both apply
 * and only conflicting declarations resolve by order.
 *
 * Explicit widths are deliberately NOT re-declared: `border-2` still means 2px.
 * A system where a named number silently meant something else would be worse
 * than one with no weight parameter at all. */
@layer utilities {
  .border { border-width: var(--stroke-hairline); }
  .border-t { border-top-width: var(--stroke-hairline); }
  .border-r { border-right-width: var(--stroke-hairline); }
  .border-b { border-bottom-width: var(--stroke-hairline); }
  .border-l { border-left-width: var(--stroke-hairline); }
  .border-x { border-inline-width: var(--stroke-hairline); }
  .border-y { border-block-width: var(--stroke-hairline); }
}

/* ── FORM — corner curvature by role (FR-21) ──────────────────────────────── */
/* `corner-shape` is a separate property from `border-radius`: it decides whether
 * the corner `rounded-{role}` already sized is a circular arc or a superellipse.
 * Binding it here, on the same three role classes the by-role radius produces,
 * is what makes every surface that already spends `rounded-controls` /
 * `rounded-containers` / `rounded-inline` pick up the smoothing with no per-site
 * change — the same "re-declare the utility to read a semantic var, land second
 * in @layer utilities and win on the one property named" mechanism the border
 * weights above rely on. Tailwind's generated `.rounded-{role}` sets
 * `border-radius`; this sets `corner-shape`; both apply.
 *
 * The default value is `superellipse(1)`, a circular arc the engine renders
 * identically to no `corner-shape` at all — so this block is inert until
 * cornerSmoothing is rolled, and a browser without `corner-shape` support
 * ignores it and keeps the arc. Zero per-frame cost: it is a paint-time property
 * like `border-radius`, not a runtime. */
@layer utilities {
  .rounded-controls { corner-shape: var(--corner-controls); }
  .rounded-containers { corner-shape: var(--corner-containers); }
  .rounded-inline { corner-shape: var(--corner-inline); }
  /* Track strokework (D17): SVG line ends follow the track family — round on a
   * capsule track, butt on a rect one. `--cap-track` is derived from
   * `--r-track` at generate time, never authored. */
  .cap-track { stroke-linecap: var(--cap-track, round); }
}

